"""Generate chapter 07 with reproducible fences and sensitivity figures."""
from pathlib import Path
from statistics import mean,median,pstdev
from html import escape
import json,re
from _build_quantiles_chapter import summary
ROOT=Path(__file__).resolve().parent

def build():
 rows=json.loads((ROOT/'example-data.json').read_text(encoding='utf-8'))['rows'];values=[r['price'] for r in rows]
 def t(x,y,s,extra=''):return f'<text x="{x}" y="{y}" {extra}>{escape(str(s))}</text>'
 def line(x,y,xx,yy,extra=''):return f'<line x1="{x}" y1="{y}" x2="{xx}" y2="{yy}" stroke="#64748b" {extra}/>'
 def fig(id,title,b,cap,h):return f'<figure class="learn-chart learn-chart--wide"><svg viewBox="0 0 640 {h}" role="img" aria-labelledby="{id}-title {id}-desc"><title id="{id}-title">{title}</title><desc id="{id}-desc">{cap}</desc>{b}</svg><figcaption class="learn-chart__caption">{cap}</figcaption></figure>'
 b=t(24,28,'울타리는 계산한 경계, 수염 끝은 실제 관측값입니다')
 x=lambda v:110+v*.95
 b+=line(x(62),90,x(268),90)+f'<rect x="{x(98)}" y="70" width="{70*.95}" height="40" fill="#bfdbfe"/>'+line(x(122),70,x(122),110)
 for v,label,y in [(-7,'하한 −7',55),(98,'Q1 98',140),(168,'Q3 168',160),(273,'상한 273',55)]:
  b+=line(x(v),65,x(v),115,'stroke-dasharray="4 3"')+t(x(v),y,label,'text-anchor="middle"')
 b+=line(x(62),83,x(62),97)+line(x(268),83,x(268),97)+t(x(62),190,'수염 62','text-anchor="middle"')+t(x(268),190,'수염 268','text-anchor="middle"')
 b+=f'<circle cx="{x(480)}" cy="90" r="6" fill="#d97706"/>'+t(x(480),65,'7번 480','text-anchor="middle"')
 b+=line(x(0),230,x(500),230)
 for v in [0,100,200,300,400,500]:b+=t(x(v),252,v,'text-anchor="middle"')
 b+=t(400,281,'단가(만원/㎡)')
 f1=fig('fences','IQR 울타리와 수염',b,'그림 1. 공통 30건의 IQR은 70, 1.5배 울타리는 −7과 273입니다. 수염은 경계 안의 실제 최솟값 62와 최댓값 268까지입니다. 별도 점 480은 검토 후보입니다.',305)
 b=t(24,28,'같은 Q1·Q3를 고정하고 배수만 바꿉니다')
 for i,k in enumerate([1.5,2,3]):
  y=85+i*75;lo=98-k*70;hi=168+k*70
  b+=t(24,y+5,f'k={k}')+line(105,y,600,y)+f'<rect x="{105+(lo+120)*.75}" y="{y-10}" width="{(hi-lo)*.75}" height="20" fill="#dbeafe" data-k="{k}" data-low="{lo}" data-high="{hi}"/>'
  b+=t(105+(lo+120)*.75,y-20,f'{lo:g}','text-anchor="middle"')+t(105+(hi+120)*.75,y-20,f'{hi:g}','text-anchor="middle"')+f'<circle cx="555" cy="{y}" r="5" fill="#d97706"/>'+t(568,y+5,'480')
 b+=t(24,285,'색칠한 구간: 하한~상한 / 주황 점: 7번')+t(370,311,'단가(만원/㎡), 동일 축척')
 f2=fig('multipliers','배수별 IQR 경계',b,'그림 2. 하한·상한은 k=1.5에서 −7·273, k=2에서 −42·308, k=3에서 −112·378입니다. 세 경우 모두 480 한 건만 경계 밖입니다.',336)
 b=t(24,28,'집단을 나누면 비교 기준도 달라집니다')
 for i,label in enumerate(['전체','주거','상업']):
  v=values if label=='전체' else [r['price'] for r in rows if r['group']==label];q1,q2,q3,lo,hi,out=summary(v);upper=q3+1.5*(q3-q1);y=90+i*100
  b+=t(24,y-28,f'{label} {len(v)}건 · Q1 {q1:g}, Q3 {q3:g}, 상한 {upper:g}')+line(90,y,590,y)
  b+=f'<rect x="{90+q1}" y="{y-10}" width="{q3-q1}" height="20" fill="#bfdbfe" data-group="{label}" data-upper="{upper}"/>'+line(90+q2,y-10,90+q2,y+10)+line(90+upper,y-17,90+upper,y+17,'stroke-dasharray="4 3"')
  for val in v:b+=f'<circle cx="{90+val}" cy="{y+25}" r="3" fill="{"#d97706" if val in out else "#2563eb"}"/>'
 for val in [0,100,200,300,400,500]:b+=t(90+val,355,val,'text-anchor="middle"')
 b+=t(420,382,'단가(만원/㎡)')
 f3=fig('group-fences','집단별 상한 비교',b,'그림 3. 공통 자료를 유형별로 나눠 다시 계산한 상한은 주거 168, 상업 401.5입니다. 전체와 상업에서는 480이 후보이고 주거에는 후보가 없습니다. 기준값 자체도 달라집니다. 점이 겹치면 여러 건이 하나로 보일 수 있습니다.',407)
 b=t(24,28,'포함·제외 비교는 결과의 민감도를 보여 줍니다')
 other=[r['price'] for r in rows if r['id']!=7]
 for i,(label,fn) in enumerate([('평균',mean),('중앙값',median),('표준편차',pstdev)]):
  y=78+i*90;b+=t(24,y+8,label)
  for offset,v,color,key in [(0,values,'#2563eb','all'),(31,other,'#d97706','without')]:
   value=fn(v);b+=f'<rect x="150" y="{y+offset-10}" width="{value*2.5}" height="18" fill="{color}" data-metric="{label}" data-series="{key}" data-value="{value}"/>'+t(158+value*2.5,y+offset+4,f'{value:.2f}')
 b+=t(24,345,'파랑: 전체 30건 / 주황: 7번 제외 29건')+t(24,373,'가로축은 모두 0에서 시작 · 단위: 만원/㎡')
 f4=fig('sensitivity','제외 전후 통계량',b,'그림 4. 표준편차는 각 집합의 건수 n으로 나눠 계산합니다. 자료가 바뀌므로 평균도 다시 구합니다. 제외 결과가 더 정확하다는 의미는 아닙니다.',398)
 parts=[]
 def sec(id,label,title,body):parts.append(f'<section class="learn-chapter__step" id="{id}" data-toc-label="{label}"><p class="learn-chapter__label">{label}</p><h2>{title}</h2>{body}</section>')
 sec('quick-start','서두 · 학습목표','다른 값들과 멀리 떨어져 있으면 지워도 될까요?','<p>대부분의 통학 시간이 20~40분인데 한 학생의 기록만 180분이라면 먼저 눈에 들어올 것입니다. 입력을 잘못했을 수도 있지만, 실제로 먼 곳에서 통학하는 학생일 수도 있습니다. 숫자가 크다는 사실만으로 어느 쪽인지 알 수는 없습니다.</p><p><strong>이상치 후보</strong>는 다른 값들과 비교해 추가로 확인할 필요가 있는 관측입니다. 후보를 찾는 규칙과 그 값을 어떻게 처리할지는 구별해야 합니다.</p><ul class="learn-objectives"><li><strong>IQR 경계</strong>를 계산하고, 경계 밖의 값과 상자그림의 수염 끝을 구별합니다.</li><li>배수·분위수 계산법·비교 집단에 따라 후보가 달라지는 이유를 설명합니다.</li><li>원자료를 확인하고 포함·제외 결과를 비교한 뒤 처리 근거를 기록하는 순서를 익힙니다.</li></ul><p>앞 장에서 배운 <a href="/learn/stats/quantiles/#iqr">사분위수와 IQR</a>, <a href="/learn/stats/spread/#extremes">큰 값이 통계량에 미치는 영향</a>을 떠올리며 읽어 보세요. 계산에는 앞 장과 같은 공통 학습 예시를 사용합니다.</p>'+f1)
 sec('iqr-multiplier','IQR 경계 계산','상자 양 끝에서 IQR의 일정 배수만큼 넓힙니다','<p><strong>IQR=Q3−Q1</strong>은 자료 가운데 부분의 퍼짐입니다. 배수 k를 정하면 다음 두 경계를 구할 수 있습니다. 이 경계를 울타리라고도 부릅니다.</p><p><strong>아래쪽 경계 L=Q1−k×IQR<br>위쪽 경계 U=Q3+k×IQR</strong></p><p>이 장에서는 x&lt;L 또는 x&gt;U인 값을 후보로 표시합니다. 경계와 같은 값은 남깁니다. 상자그림의 수염은 계산한 경계까지가 아니라 그 안에 있는 실제 관측값까지 그립니다.</p><p><a href="/learn/stats/graphs/#data">공통 학습 예시 30건</a>의 Q1은 98, Q3는 168, IQR은 70입니다. k=1.5이면 아래쪽 경계는 98−105=−7, 위쪽은 168+105=273입니다. 62와 268은 경계 안에 있고, <strong>480 한 건만 경계 밖</strong>입니다. 아래쪽 경계가 음수인 것은 계산 결과이지 음수 값을 관측했다는 뜻이 아닙니다.</p>'+f2+'<p>같은 자료와 사분위수를 유지하면 k를 키울수록 경계가 넓어집니다. 후보는 줄거나 그대로이며 늘지는 않습니다. 이 예시에서는 273과 378 사이에 관측이 없어 k=1.5·2·3에서 모두 480 한 건이 후보입니다.</p><p>1.5배는 널리 쓰이는 탐색 규칙이고 3배 경계도 사용합니다. 배수는 후보를 얼마나 넓게 찾을지 정하는 선택입니다. <strong>IQR 경계는 신뢰구간이나 오류 확률을 뜻하지 않습니다.</strong> 제외한 뒤 사분위수를 다시 계산하는 절차는 이 고정된 경계 비교와 다릅니다.</p>')
 sec('conventions','계산법과 예외','같은 자료인데 후보가 달라질 수도 있습니다','<p>이 장에서는 자료를 정렬해 두 절반으로 나누고 각 절반의 중앙값을 Q1·Q3로 삼습니다. 홀수 개라면 전체 중앙 관측을 양쪽 절반에서 제외합니다. <a href="/learn/stats/quantiles/#methods">분위수 계산법</a>을 바꾸면 IQR과 경계도 바뀔 수 있습니다.</p><p>공통 예시에 type 7 선형 보간을 쓰면 Q1=99, Q3=166, IQR=67입니다. 1.5배 경계는 −1.5와 266.5가 되어 268과 480 두 건이 후보가 됩니다. 앞 절에서 후보가 아니었던 268이 이번에는 경계 밖에 놓입니다.</p><p>표본이 작으면 몇 개의 값이 사분위수 위치를 크게 바꿀 수 있습니다. 같은 값이 많아 <strong>IQR이 0</strong>인 경우도 주의해야 합니다. 100·100·100·100·100·100·120은 이 장의 계산법에서 Q1=Q3=100입니다. 경계도 100에 겹쳐 120이 후보가 되지만, 이것만으로 120이 오류라고 말할 수는 없습니다.</p><p>후보를 빼고 경계를 다시 구하는 작업을 반복하면 처음에는 남았던 값도 나중에 제외될 수 있습니다. 한 번 계산한 경계를 쓰는지, 반복하는지 기록하세요. 원하는 결과가 나올 때까지 배수나 규칙을 바꾸지 않습니다.</p>')
 sec('groups','집단과 분포','무엇과 비교했는지도 판단의 일부입니다','<p>전교생의 키를 한꺼번에 비교할 때와 학년별로 나누어 비교할 때는 기준이 다릅니다. 전체에서는 드문 값이어도 같은 학년 안에서는 흔한 값일 수 있습니다. <strong>비교 집단을 먼저 정한 뒤 그 집단의 사분위수를 구해야 합니다.</strong></p><p>공통 학습 예시를 전체와 유형별로 나누어 같은 1.5×IQR 규칙을 적용해 보겠습니다.</p>'+f3+'<p>주거 15건의 IQR은 32, 위쪽 경계는 168입니다. 상업 15건의 IQR은 111, 위쪽 경계는 401.5입니다. 전체 IQR 70을 두 집단에 그대로 적용한 결과와는 기준 자체가 다릅니다.</p><p>집단을 너무 잘게 나누면 각 집단의 표본 수가 적어져 경계가 불안정해질 수 있습니다. 분석 목적과 자료 수를 함께 고려해 비교할 범위를 정하세요.</p><p>IQR 계산에 정규분포 가정은 필요하지 않습니다. 다만 한쪽 꼬리가 긴 자료에서는 경계 밖의 값도 자연스럽게 나타날 수 있습니다. 서로 다른 집단이 섞였는지 히스토그램과 산점도도 함께 봅니다. 한 변수의 IQR만으로 두 변수의 관계에서 드러나는 특이한 관측까지 모두 찾아낼 수는 없습니다.</p>')
 sec('sensitivity','포함·제외 비교','숫자가 바뀐 정도와 바뀐 이유를 함께 봅니다','<p>경계 밖의 값을 제외하기 전에 그 값이 결과에 얼마나 영향을 주는지 비교해 볼 수 있습니다. 실제 거래 출처가 확인되지 않은 공통 학습 예시에서 7번 480을 제외한 결과를 살펴보겠습니다.</p>'+f4+'<p>평균은 146.33에서 134.83, 중앙값은 122에서 120으로 바뀝니다. 각 자료의 건수 n으로 나눈 표준편차는 80.16에서 51.72로 줄어듭니다. 자료를 제외했으므로 평균과 퍼짐도 남은 자료로 다시 구했습니다.</p><p>평균과 표준편차가 크게 달라지는 것은 큰 값의 영향과 연결됩니다. 중앙값과 IQR은 꼬리의 일부 값에 상대적으로 덜 민감하지만 항상 변하지 않는 것은 아닙니다.</p><p><strong>값이 작아지거나 그래프가 매끈해졌다고 더 정확해진 것은 아닙니다.</strong> 유효한 관측을 제외하면 설명하는 대상이 달라질 수 있습니다. 포함·제외 비교는 결과의 민감도를 확인하는 데 쓰고, 처리 결정은 자료의 맥락과 근거에 따라 내립니다.</p>')
 sec('workflow','확인과 처리','표시하고, 확인하고, 비교한 뒤 근거를 남깁니다','<ol><li><strong>대상을 정합니다.</strong> 관측 단위, 측정한 변수와 단위, 비교 집단을 확인합니다.</li><li><strong>후보를 표시합니다.</strong> 사분위수 계산법, 배수 k, 경계 처리 규칙, 기준 건수와 후보 목록을 기록합니다.</li><li><strong>원자료를 확인합니다.</strong> 단위 입력, 중복, 기록 정정 여부와 측정 조건을 대조합니다. 큰 숫자만으로 원인을 추측하지 않습니다.</li><li><strong>처리 방법을 정합니다.</strong> 확인된 오류는 근거에 따라 정정하고, 성격이 다른 유효한 집단은 나눠 분석할 수 있습니다. 판단 근거가 부족하면 원자료를 유지하고 민감도 비교를 제시합니다.</li><li><strong>전후 결과를 설명합니다.</strong> 제외 사유와 건수, 달라진 통계량을 남깁니다. 나중에 다시 확인할 수 있도록 원자료도 보존합니다.</li></ol><details class="learn-more"><summary>절사와 윈저화는 어떻게 다른가요?</summary><div class="learn-more__body"><p><strong>절사</strong>는 정한 규칙에 따라 일부 관측을 분석에서 제외합니다. <strong>윈저화</strong>는 극단의 값을 정한 경계값으로 바꿉니다. 전자는 분석 건수를 줄이고 후자는 값을 바꾸므로 분포에 미치는 영향이 다릅니다.</p><p>어느 방법도 자동으로 오류를 교정하지는 않습니다. 적용했다면 기준과 이유를 밝히고 원자료와 구별해 보관해야 합니다.</p></div></details>')
 sec('practice','확인 문제','후보를 찾는 규칙과 제외 결정을 구별해 보세요','<ol class="learn-exercises"><li>Q1=98, Q3=168, k=1.5라면 273도 후보인가요?<details><summary>답과 해설</summary><p>아니요. 위쪽 경계가 273이고 이 장의 규칙은 경계를 포함합니다. 273보다 큰 값이 후보입니다. 실제 공통 자료에는 273이 없습니다.</p></details></li><li>k를 1.5에서 3으로 키우면 후보가 반드시 줄어들까요?<details><summary>답과 해설</summary><p>같은 자료와 사분위수를 유지하면 줄거나 그대로입니다. 공통 예시에서는 두 경우 모두 480 한 건입니다.</p></details></li><li>한 프로그램은 480만, 다른 프로그램은 268과 480을 표시합니다. 반드시 오류일까요?<details><summary>답과 해설</summary><p>아니요. 두 절반의 중앙값 방식에서는 위쪽 경계가 273, type 7에서는 266.5가 됩니다. 먼저 분위수 계산법과 경계 처리, 비교 집단이 같은지 확인하세요.</p></details></li></ol>')
 sec('macro','CH2 Macro에서 읽기','체크 여부와 배수를 확인하고 분석을 실행합니다','<p>CH2 Macro 토지 필터의 <strong>‘이상치 제외 (IQR)’</strong>는 IQR 기준으로 분석 대상에서 일부 거래를 제외하는 옵션입니다. 아래는 설정 위치를 보여 주는 화면입니다.</p><figure class="learn-capture learn-capture--detail"><a href="../assets/captures/land-iqr-filter-options.png" target="_blank" rel="noopener" aria-label="IQR 이상치 제외 설정 화면 크게 보기"><img src="../assets/captures/land-iqr-filter-options.png" width="436" height="181" loading="lazy" alt="CH2 Macro 이상치 제외 IQR 설정. 체크박스는 해제되어 있고 배수 1.5·2·3은 흐리게 표시됩니다. 아래에는 필터 분석 실행 버튼이 있습니다."/></a><figcaption class="learn-capture__caption">IQR 필터 설정 화면입니다. 캡처에서는 ‘이상치 제외 (IQR)’가 체크되지 않아 배수 선택이 비활성화되어 있습니다. 후보 건수나 제외 후 결과를 보여 주는 화면은 아닙니다. <a href="../assets/captures/land-iqr-filter-options.png" target="_blank" rel="noopener">원본 크게 보기 ↗</a></figcaption></figure><ol class="learn-screen-reading"><li><strong>적용 여부:</strong> 캡처에서는 체크박스가 해제되어 있습니다. 아래에 배수 3이 표시되어 있어도 이 상태에서는 IQR 제외 옵션을 켠 것이 아닙니다.</li><li><strong>배수 선택:</strong> 체크박스를 켜면 k=1.5·2·3 중 하나를 고를 수 있습니다. 같은 자료와 사분위수라면 큰 배수일수록 경계가 넓어져 제외 대상은 줄거나 그대로입니다.</li><li><strong>분석 실행:</strong> 조건을 정한 뒤 ‘필터 분석 실행’을 누릅니다. 결과에서 IQR 적용 여부와 전후 건수를 확인하세요. 선택한 지역·기간·유형 같은 다른 조건도 같게 맞춰야 비교할 수 있습니다.</li><li><strong>산식 확인:</strong> 물음표 도움말에서 적용 변수와 비교 범위, 분위수 산식과 제외 규칙을 확인합니다. 교재의 손계산 예시가 서비스의 모든 계산과 같다고 가정하지 않습니다.</li></ol><p>원래 결과와 IQR 적용 결과를 비교해 평균·중앙값·표준편차가 얼마나 달라졌는지 살펴보세요. <strong>필터에서 제외되었다는 것은 이번 분석 대상에서 빠졌다는 뜻</strong>입니다. 원자료가 삭제되거나 해당 거래가 오류라고 확정된 것은 아닙니다.</p><p>설정 화면만으로는 몇 건이 제외됐는지 알 수 없습니다. 실제 결과의 건수와 제외 기준을 함께 기록해야 다른 분석과 비교할 수 있습니다.</p><p class="learn-macro-cta"><a href="https://macro.ch2data.com/land/">CH2 Macro 토지에서 확인하기 →</a></p>')
 sec('recap','결론 · 학습 요약','경계 밖이라는 표시를 처리의 근거와 구별하세요','<p>IQR은 멀리 떨어진 값을 살펴보는 출발점입니다. 다음 순서와 기준을 기억해 두세요.</p><ul class="learn-recap-list"><li><strong>경계 계산:</strong> IQR=Q3−Q1이며 아래·위 경계는 Q1−k×IQR과 Q3+k×IQR입니다.</li><li><strong>규칙 확인:</strong> 배수, 분위수 계산법, 경계 포함 여부와 비교 집단에 따라 후보가 달라질 수 있습니다.</li><li><strong>원자료 확인:</strong> 경계 밖의 값이 곧 오류는 아닙니다. 단위·기록 과정·대상의 특성을 확인합니다.</li><li><strong>민감도 비교:</strong> 포함·제외 결과와 건수를 함께 보고, 수치가 작아졌다는 이유만으로 더 정확하다고 판단하지 않습니다.</li><li><strong>처리 기록:</strong> 정정·제외·유지의 근거를 남기고 원자료를 보존합니다.</li></ul><p>다음 <a href="/learn/stats/probability/">8장 ‘확률의 기초와 조건부확률’</a>에서는 사건과 확률을 표현하고 조건에 따라 분모가 어떻게 달라지는지 배웁니다.</p><details class="learn-more"><summary>참고자료</summary><div class="learn-more__body"><ul><li><a href="https://www.itl.nist.gov/div898/handbook/eda/section3/boxplot.htm">NIST/SEMATECH: Box Plot</a> — 상자그림과 IQR 경계.</li><li><a href="https://www.itl.nist.gov/div898/handbook/eda/section3/eda35h.htm">NIST/SEMATECH: Detection of Outliers</a> — 후보 표시와 원자료 확인.</li></ul><p class="learn-source-note">참고자료의 기존 확인일: 2026-10-07. 본문의 네 그림은 공통 학습 자료로 계산했습니다. 실제 거래 출처가 확인되지 않아 특정 시장의 통계로 사용하지 않습니다.</p></div></details>')
 p=ROOT/'iqr-outliers/index.html';s=p.read_text(encoding='utf-8');s=re.sub(r'<article.*?</article>','<article class="learn-chapter learn-chapter--expanded learn-chapter--edited" aria-label="이상치와 IQR">\n'+'\n'.join(parts)+'\n</article>',s,count=1,flags=re.S)
